[3903] = { en = "Milly Osworth", tier = 1,
  t = "Milly Osworth",
  d = "Je hebt laten zien dat je een betrouwbare $c bent, $N. Betrouwbaar, en je bent niet bang om je handen vuil te maken, hè?$B$BIk heb een vriendin, Milly Osworth. Ze heeft problemen. Ze staat met haar wagen aan de andere kant van de abdij, bij de stal. Ze kan vast een paar handen zoals die van jou gebruiken.",
