[3904] = { en = "Milly's Harvest", tier = 1,
  t = "Milly's oogst",
  d = "Een bende rovers, de Defias, kwam in de Northshire Vineyards terwijl ik aan het oogsten was! Ik heb het aan de wachters van Northshire verteld. Ze zeiden dat ze het zouden oplossen, maar... ik ben bang voor mijn druiven! Als de Defias ze niet stelen, dan vertrappen onze wachters ze misschien als ze de boeven wegjagen.$B$BAlsjeblieft, je moet me helpen! Ik heb de meeste druiven in emmers gedaan. Maar ik heb ze in de wijngaarden laten staan, in het zuidoosten.$B$BBreng me die kratten! Red mijn oogst!",
  o = "Breng 8 kratten Milly's Harvest naar Milly Osworth bij Northshire Abbey.",
  p = "Heb je mijn oogst, $N?",
  c = "O, dank je, $N! Je hebt mijn oogst gered! En ik hoop dat je een paar van die Defias hebt laten zien dat ze hier geen problemen kunnen maken.$B$BWe hebben nu misschien weinig wachters, maar we hebben geluk dat er helden zoals jij zijn om ons te beschermen!",
