[54] = { en = "Report to Goldshire", tier = 1,
  t = "Meld je in Goldshire",
  d = "$N, je bent een $c die laat zien dat de veiligheid van Northshire belangrijk voor je is. Nu krijg je een nieuwe taak: je beschermt het Elwynn Forest eromheen.$B$BAls je deze taak aanneemt, heb ik papieren voor je. Die moet je naar Marshal Dughan in Goldshire brengen. Goldshire ligt aan de weg naar het zuiden, voorbij de grenspoorten.",
