[47] = { en = "Gold Dust Exchange", tier = 1,
  t = "Goudstof ruilen",
  d = "De kobolds hier hebben soms Gold Dust bij zich. Ik kan dat spul heel goed gebruiken. Breng me een flinke lading en je krijgt de beste prijs van de stad... de beste prijs van de stad!$B$BJe vindt kobolds in de Fargodeep Mine in het zuiden, en rond de Jasperlode Mine in het noordoosten.",
  o = "Breng 10 Gold Dust naar Remy \"Two Times\" in Goldshire. Je krijgt Gold Dust van kobolds in Elwynn Forest.",
  p = "Psst! Heb je dat Gold Dust voor me... voor me?",
  c = "Bedankt voor het stof, $N. Hier is je geld, en... hier is een teken van een paar zakenvrienden van me. Misschien heb je er iets aan... iets aan.",
  g = { {"Goudstof", "gold dust"}, {"bij zich", "on them, with them"}, {"spul", "stuff"}, {"flinke", "big, decent (flink)"}, {"lading", "load"}, {"stof", "dust"}, {"teken", "token, sign"}, {"zakenvrienden", "business associates (zakenvriend)"}, {"heb je er iets aan", "it's of use to you"} },
},

[60] = { en = "Kobold Candles", tier = 1,
  t = "Koboldkaarsen",
  d = "Hallo, $gmeneer:mevrouw;! Heb je even tijd?$B$BMijn broer en ik hebben een apotheek in Stormwind. Ik ben hier om grote kaarsen te verzamelen, voor hun was. Kun je me helpen?$B$BJe kunt grote kaarsen krijgen van kobolds. Ik hoor geruchten dat er veel kobolds in de mijnen van Elwynn zitten... de Fargodeep Mine in het zuiden en de Jasperlode Mine in het oosten. Zoek op een van die plekken naar kaarsen.",
  o = "Breng 8 Large Candles naar William Pestle in Goldshire.",
  p = "Heb je die kaarsen al verzameld?",
  c = "Je was druk bezig met kobolds jagen, hè? Bedankt voor de kaarsen, $N. Hier is je beloning...",
  g = { {"kaarsen", "candles (kaars)"}, {"Heb je even tijd", "do you have a moment"}, {"apotheek", "apothecary"}, {"verzamelen", "to gather"}, {"was", "wax"}, {"geruchten", "rumours (gerucht)"}, {"mijnen", "mines (mijn)"}, {"plekken", "places (plek)"}, {"beloning", "reward"} },
},

[61] = { en = "Shipment to Stormwind", tier = 1,
  t = "Zending naar Stormwind",
  d = "Mijn broer Morgan wacht in Stormwind op mijn zending kaarsen. Ik heb niet genoeg tijd om zelf te gaan. Maar als jij hem de zending wilt brengen, betaalt hij je goed.$B$BIk heb de kaarsen ingepakt. Je vindt Morgan in onze winkel, Pestle's Apothecary, in het Stormwind Trade District.",
  o = "Breng William's Shipment naar Morgan Pestle in het Stormwind Trade District.",
  p = "O, een zending van mijn broer? Geweldig! Het geluk lacht me vandaag echt toe!",
  c = "Hier is je betaling... en kijk gerust even rond nu je hier bent! We hebben vast een toverdrank of een ander snuisterijtje dat je nuttig vindt.",
  g = { {"Zending", "shipment"}, {"betaalt", "pays (betalen)"}, {"ingepakt", "packed up (inpakken)"}, {"winkel", "shop"}, {"Het geluk lacht me toe", "fortune smiles on me (toelachen)"}, {"betaling", "payment"}, {"kijk rond", "look around (rondkijken)"}, {"gerust", "feel free to"}, {"toverdrank", "potion"}, {"snuisterijtje", "trinket (snuisterij)"} },
},

[62] = { en = "The Fargodeep Mine", tier = 1,
  t = "De Fargodeep Mine",
  d = "De mijn in Northshire is niet de enige met problemen! Ik heb berichten gekregen dat de Fargodeep Mine in Elwynn ook een veilige plek voor kobolds is geworden.$B$BVerken de mijn en kijk of de berichten kloppen. Kom dan terug naar mij. De mijn ligt bijna recht ten zuiden van Goldshire, tussen de boerderijen van Stonefield en Maclure.",
  o = "Verken de Fargodeep Mine en ga dan terug naar Marshal Dughan in Goldshire.",
  p = "Wat heb je te melden, $N? Ben je bij de Fargodeep Mine geweest?",
  c = "Dit is slecht nieuws. Wat nu weer, draken?!? We moeten meer patrouilles bij die mijn sturen. Bedankt voor je moeite, $N. En wacht even... misschien heb ik nog een taak voor je.",
  e = "Verken de Fargodeep Mine",
  g = { {"de enige", "the only one"}, {"berichten", "reports (bericht)"}, {"veilige plek", "safe place, haven"}, {"Verken", "explore (verkennen)"}, {"kloppen", "are correct (kloppen)"}, {"recht ten zuiden", "due south"}, {"te melden", "to report (melden)"}, {"draken", "dragons (draak)"}, {"patrouilles", "patrols (patrouille)"}, {"moeite", "effort"} },
},

[112] = { en = "Collecting Kelp", tier = 1,
  t = "Kelp verzamelen",
  d = "Ik kan een onzichtbaarheidsdrank maken voor Maybell. Dan kan ze stiekem weg uit de Maclure Vineyards en naar Tommy Joe gaan. Maar om die drank te maken, heb ik wat kristalkelp nodig.$B$BKelp groeit meestal in de oceaan... maar soms verzamelen murlocs het. Kijk of de murlocs bij Crystal Lake wat hebben. Crystal Lake ligt vlak ten oosten van Goldshire.",
  o = "Breng 4 Crystal Kelp Fronds naar William Pestle in Goldshire.",
  p = "Heb je die kristalkelp? Maybell wil vast heel graag haar liefje zien...",
  c = "Je hebt ze. Goed gedaan! Nu even wachten terwijl ik de toverdrank maak...",
  g = { {"Kelp", "kelp"}, {"onzichtbaarheidsdrank", "invisibility liquor"}, {"stiekem", "secretly, sneakily"}, {"kristalkelp", "crystal kelp"}, {"groeit", "grows (groeien)"}, {"oceaan", "ocean"}, {"vlak", "just, right"}, {"liefje", "sweetheart, beau"}, {"terwijl", "while"}, {"toverdrank", "potion"} },
},

[114] = { en = "The Escape", tier = 1,
  t = "De ontsnapping",
  d = "Breng deze onzichtbaarheidsdrank naar de jonge Maybell. Hij werkt lang genoeg om Tommy Joe te bezoeken.",
  o = "Breng de Invisibility Liquor naar Maybell Maclure.",
  p = "Heb je mijn brief aan Tommy Joe gegeven? Wat zei hij??",
  c = "O... jee! Ik voel me schuldig omdat ik mijn familie bedrieg. Maar mijn gevoelens voor Tommy Joe zijn te sterk om te negeren.$B$BDank je, $N. Ik drink deze drank zodra ik de kans heb. Dan sluip ik weg naar mijn liefde.$B$BEn voor jou... neem dit alsjeblieft.",
  g = { {"ontsnapping", "escape"}, {"onzichtbaarheidsdrank", "invisibility liquor"}, {"bezoeken", "to visit"}, {"schuldig", "guilty"}, {"bedrieg", "deceive (bedriegen)"}, {"gevoelens", "feelings (gevoel)"}, {"negeren", "to ignore"}, {"zodra", "as soon as"}, {"kans", "chance"}, {"sluip weg", "sneak away (wegsluipen)"} },
},

[87] = { en = "Goldtooth", tier = 1,
  t = "Goldtooth",
  d = "Ik speelde bij de Fargodeep Mine, en ik denk dat ik de ketting van die oude vrouw liet vallen, eh... ik bedoel, zag! Vraag me niet hoe die daar kwam... ik was het niet!$B$BNou ja, ik zag een grote kobold met een gouden tand. Hij pakte de ketting op en rende de mijn in. Zoek die kobold en je vindt de ketting, dat zweer ik!",
  o = "Breng Bernice's Necklace naar \"Auntie\" Bernice Stonefield op de Stonefield Farm.",
  p = "Hallo, $N. Heb je mijn ketting gevonden?",
  c = "O, je hebt hem gevonden! Dank je, dank je, lieverd!$B$BHier, neem dit. Het was van mijn man. Hij zei altijd dat het geluk bracht. Had hij het maar niet vergeten op zijn laatste veldtocht! *snif*",
  g = { {"ketting", "necklace"}, {"liet vallen", "dropped (laten vallen)"}, {"ik bedoel", "I mean"}, {"gouden tand", "gold tooth"}, {"pakte op", "picked up (oppakken)"}, {"rende", "ran (rennen)"}, {"dat zweer ik", "I swear (zweren)"}, {"lieverd", "dear"}, {"geluk bracht", "was lucky, brought luck (brengen)"}, {"Had hij maar", "if only he had"}, {"veldtocht", "campaign"} },
},

[83] = { en = "Red Linen Goods", tier = 1,
  t = "Rode linnen spullen",
  d = "De Defias-bende in Northshire draagt maskers van jute. Maar de Defias in Elwynn dragen linnen. Daar kan ik mooie linnen spullen van maken.$B$BBreng me rode linnen bandana's. Dan maak ik er iets voor je van.$B$BDe leden van de Defias-bende hebben kampen overal in Elwynn.",
  o = "Breng 6 Red Linen Bandanas naar Sara Timberlain in het Eastvale Logging Camp.",
  p = "Mijn linnen raakt op, $N. Heb je wat voor me?",
  c = "Ah, dit zijn mooie bandana's, al zijn ze een beetje ruw...$B$BAlsjeblieft!",
  g = { {"linnen", "linen"}, {"spullen", "goods, things"}, {"bende", "gang"}, {"maskers", "masks (masker)"}, {"jute", "burlap"}, {"leden", "members (lid)"}, {"raakt op", "is running low (oprakken)"}, {"al zijn ze", "even if they are"}, {"ruw", "rough"} },
},

[88] = { en = "Princess Must Die!", tier = 1,
  t = "Princess moet dood!",
  d = "De Brackwells hebben een varken dat prijzen wint: Princess. De zeug is ENORM. Ze is zo groot geworden omdat ze hierheen sluipt en mijn groenten eet!$B$BDus voordat ze naar onze akkers komt... moet Princess dood! Breng me haar halsband als bewijs. Dan geef ik je iets voor je moeite.$B$BPrincess is meestal bij de Brackwell Pumpkin Patch, in het oosten, voorbij de boerderij van Maclure. Pak haar voordat ze honger krijgt en hier terugkomt!",
  o = "Dood Princess, pak haar halsband en breng hem terug naar Ma Stonefield op de Stonefield Farm.",
  p = "Heb je haar al gezien? Heb je haar gepakt?",
  c = "Godzijdank! Dat varken werd zo groot, ze zou onze hele oogst hebben opgegeten! Dank je, $N.$B$BNou, wil je een van deze?",
  g = { {"varken", "pig"}, {"prijzen", "prizes (prijs)"}, {"zeug", "sow"}, {"sluipt", "sneaks (sluipen)"}, {"groenten", "vegetables (groente)"}, {"akkers", "fields (akker)"}, {"halsband", "collar"}, {"bewijs", "proof"}, {"moeite", "trouble, effort"}, {"Godzijdank", "thank goodness"}, {"oogst", "crop, harvest"}, {"opgegeten", "eaten up (opeten)"} },
},

[5545] = { en = "A Bundle of Trouble", tier = 1,
  t = "Een bundel problemen",
  d = "Ik heb echt een probleem. Er komt een deadline aan voor een bestelling hout, en mijn tijd raakt op. De wolven en beren ten noorden van hier hebben mijn arbeiders weggejaagd. Nu kunnen ze niet bij de bundels hout die ze al gehakt hebben.$B$BIk heb al met Deputy Rainer gepraat over het wegjagen van de dieren. Maar ik heb iemand nodig die het hout voor me ophaalt. Als jij acht bundels hout voor me verzamelt, haal ik misschien mijn deadline nog.",
  o = "Breng 8 Bundles of Wood naar Raelen in het Eastvale Logging Camp.",
  p = "Die deadline komt niet verder weg, $c. Schiet alsjeblieft op en verzamel die bundels hout.",
  c = "Uitstekend! Dankzij jou kan ik de bestelling op tijd afmaken. Om je te bedanken wil ik je wat geld geven voor je moeite.$B$BBedankt en vaarwel.",
  g = { {"bundel", "bundle"}, {"bestelling", "order"}, {"raakt op", "is running out (oprakken)"}, {"arbeiders", "workers (arbeider)"}, {"weggejaagd", "chased away (wegjagen)"}, {"gehakt", "chopped (hakken)"}, {"ophaalt", "collects (ophalen)"}, {"haal mijn deadline", "make my deadline (halen)"}, {"Schiet op", "hurry up (opschieten)"}, {"Uitstekend", "excellent"}, {"Dankzij", "thanks to"}, {"afmaken", "to complete"}, {"vaarwel", "farewell"} },
},

[11] = { en = "Riverpaw Gnoll Bounty", tier = 1,
  t = "Premie op Riverpaw-gnolls",
  d = "Gnolls zijn wrede wezens die niets te zoeken hebben in deze landen. Ze zijn gezien langs de grenzen van Elwynn Forest. Een grote groep van hen zit in het bos ten zuiden van de wachttoren daar. Het zijn er veel meer dan we alleen aankunnen. Een andere groep zit in de buurt van Stone Cairn Lake, in het oosten.$B$BHet Stormwind Army zal iedereen prijzen die helpt om ze te doden. Breng me hun beschilderde gnoll-armbanden als bewijs.",
  o = "Breng 8 Painted Gnoll Armbands naar Deputy Rainer bij de Barracks.",
  p = "Gegroet, $N. Heb je gnolls gedood...?",
  c = "Ik zie dat je druk bezig bent geweest! Bedankt, $N.",
  g = { {"Premie", "bounty"}, {"wrede", "brutish, cruel (wreed)"}, {"wezens", "creatures (wezen)"}, {"niets te zoeken hebben", "have no business (being somewhere)"}, {"grenzen", "borders (grens)"}, {"wachttoren", "guard tower"}, {"aankunnen", "can handle"}, {"prijzen", "praise, commend"}, {"beschilderde", "painted (beschilderd)"}, {"armbanden", "armbands (armband)"}, {"Gegroet", "hail, greetings"} },
},

[35] = { en = "Further Concerns", tier = 1,
  t = "Meer zorgen",
  d = "Ben je bang dat de geruchten over murlocs waar zijn? Doe dan dit: ga naar de oostelijke brug van Elwynn en spreek met Guard Thomas. Hij staat al een week bij de brug. Hij weet hoe het in het gebied gaat.$B$BBreng me zijn verslag.",
  o = "Marshal Dughan wil dat je met Guard Thomas spreekt.",
  c = "Ja, murlocs wonen nu in en rond de beken van oostelijk Elwynn. We weten niet waarom ze hier zijn. Maar ze zijn agressief en ten minste een beetje intelligent.",
  g = { {"zorgen", "concerns, worries (zorg)"}, {"geruchten", "rumours (gerucht)"}, {"oostelijke", "eastern (oostelijk)"}, {"gebied", "area"}, {"verslag", "report"}, {"beken", "streams (beek)"}, {"agressief", "aggressive"}, {"ten minste", "at least"} },
},

[37] = { en = "Find the Lost Guards", tier = 1,
  t = "Zoek de verdwenen wachters",
  d = "Een paar dagen geleden hebben we twee wachters, Rolf en Malakai, langs de rivier gestuurd om te zoeken. Ze zijn nog niet terug. Voor mijn verslag moet ik weten wat er met die mannen is gebeurd.$B$BGa naar het noorden langs de rivier en zoek de wachters... of wat er van ze over is.",
  o = "Guard Thomas wil dat je naar het noorden gaat, de rivier op, en de twee verdwenen wachters zoekt: Rolf en Malakai.",
  c = "Er is veel van het lijk weggehaald. Maar vlakbij ligt een medaillon met de woorden \"Footman Malakai Stone\" erin gegraveerd.",
  g = { {"verdwenen", "lost, vanished (verdwijnen)"}, {"wachters", "guards (wachter)"}, {"gebeurd", "happened (gebeuren)"}, {"wat er van ze over is", "what is left of them, their remains"}, {"lijk", "corpse"}, {"weggehaald", "taken away, stripped (weghalen)"}, {"vlakbij", "nearby"}, {"medaillon", "medallion"}, {"gegraveerd", "engraved, etched (graveren)"} },
},

[39] = { en = "Deliver Thomas' Report", tier = 1,
  t = "Breng het verslag van Thomas",
  d = "Vertel Marshal Dughan dat Malakai en Rolf dood zijn. En meld hem dat we de murlocs in oostelijk Elwynn niet kunnen tegenhouden met de soldaten die we nu hebben.$B$BIk weet dat we niet veel soldaten over hebben, maar hopelijk kan Dughan iemand vinden.",
  o = "Breng verslag uit bij Marshal Dughan in Goldshire.",
  c = "Hm, dit nieuws is zorgwekkend. Onze verdediging is al dun, en nu we Rolf en Malakai aan die murlocs hebben verloren, staan we er nog slechter voor.$B$BAls het niet beter wordt, wordt er aan het eind van de week gevochten in Goldshire!",
  g = { {"meld", "report (melden)"}, {"tegenhouden", "to contain, stop"}, {"over hebben", "to have to spare"}, {"hopelijk", "hopefully"}, {"zorgwekkend", "troubling, worrying"}, {"verdediging", "defence"}, {"dun", "thin"}, {"verloren", "lost (verliezen)"}, {"staan we er slechter voor", "we are in a worse position (ervoor staan)"}, {"gevochten", "fought (vechten)"} },
},

[40] = { en = "A Fishy Peril", tier = 1,
  t = "Een vissig gevaar",
  d = "$N, er is een nieuw gevaar in Elwynn Forest! Murlocs zwemmen de beken van oostelijk Elwynn op. Ze jagen de vissen weg en vallen vredige mensen aan!$B$BIk heb Marshal Dughan gewaarschuwd, maar hij maakt zich meer zorgen over de gnolls en de bandieten. Hij gelooft niet dat de murlocs gevaarlijk zijn.$B$BAlsjeblieft, $N, praat met Dughan. Overtuig hem om meer soldaten naar het oosten te sturen!",
  o = "Remy \"Two Times\" wil dat je met Marshal Dughan in Goldshire spreekt.",
  c = "Ja, ik heb met Remy gepraat. Ik respecteer hem als handelaar. Maar alle berichten over murlocs in het oosten zijn op z'n best vaag.$B$BIk hoor je zorgen. Maar als ik geen militair verslag krijg over een murlocgevaar, kunnen we het ons niet veroorloven om meer soldaten naar het oosten te sturen.",
  g = { {"vissig", "fishy"}, {"beken", "streams (beek)"}, {"jagen weg", "scare away (wegjagen)"}, {"vallen aan", "attack (aanvallen)"}, {"vredige", "peaceful, gentle (vredig)"}, {"gewaarschuwd", "warned (waarschuwen)"}, {"maakt zich zorgen", "worries (zich zorgen maken)"}, {"bandieten", "bandits (bandiet)"}, {"Overtuig", "persuade (overtuigen)"}, {"handelaar", "merchant"}, {"op z'n best", "at best"}, {"vaag", "vague, sketchy"}, {"militair", "military"}, {"het ons niet veroorloven", "can't afford it (zich veroorloven)"} },
},

[45] = { en = "Discover Rolf's Fate", tier = 1,
  t = "Wat gebeurde er met Rolf?",
  d = "Je zoekt verder in het gebied. Je vindt voetafdrukken met zwemvliezen die naar het oosten gaan, langs de oever van Stone Cairn Lake. Ver in het oosten zie je nog net een murlocdorp.$B$BMisschien vond Rolf daar zijn einde...",
  o = "Zoek in het murlocdorp naar Rolf, of naar tekenen van zijn dood.",
  c = "Om de nek van het lijk vind je een metalen medaillon met de woorden \"Footman Rolf Hartford\" erin.",
  g = { {"verder", "further"}, {"voetafdrukken", "footprints (voetafdruk)"}, {"zwemvliezen", "webbing, webbed feet (zwemvlies)"}, {"oever", "shore"}, {"nog net", "just barely"}, {"murlocdorp", "murloc village"}, {"vond zijn einde", "met his end (vinden)"}, {"tekenen", "signs (teken)"}, {"lijk", "corpse"}, {"metalen", "metal"}, {"medaillon", "medallion"} },
},

[46] = { en = "Bounty on Murlocs", tier = 1,
  t = "Premie op murlocs",
  d = "Het Stormwind Army heeft een premie gezet op Murloc Lurkers en Murloc Foragers in Elwynn. Dood ze en breng me hun gescheurde murlocvinnen. Dan krijg je een goede beloning van het Stormwind Army.$B$BDe murlocs hebben een dorp gebouwd bij Stone Cairn Lake, ten noorden van hier. En nog een in het zuiden, waar de beek splitst.",
  o = "Breng 8 Torn Murloc Fins naar Guard Thomas bij de oostelijke brug van Elwynn.",
  p = "Hoe gaat de jacht, $N?",
  c = "Heb je de vinnen? Geweldig! Marshal Dughan maakt zich zorgen over de murlocs in oostelijk Elwynn. Ik zou hem graag vertellen dat we het onder controle krijgen.$B$BDat komt door jouw acties.",
  g = { {"premie", "bounty"}, {"gescheurde", "torn (gescheurd)"}, {"murlocvinnen", "murloc fins (vin)"}, {"beloning", "reward"}, {"gebouwd", "built (bouwen)"}, {"beek", "stream"}, {"splitst", "forks, splits (splitsen)"}, {"vinnen", "fins (vin)"}, {"onder controle", "under control"}, {"acties", "actions (actie)"} },
},

[1477] = { en = "Vital Supplies", tier = 3,
