  d = "Onze magiërs doen onderzoek in Nethergarde Keep in de Blasted Lands. Dat onderzoek is van groot belang om de Dark Portals te begrijpen. Ze hebben bijna voortdurend voorraden nodig, maar onze aanvoerlijn naar Nethergarde is wankel.$B$BJe moet helpen zorgen dat de voorraden Nethergarde bereiken. Meld je bij Watchmaster Sorigal in Darkshire en doe wat hij vraagt. Deze taak brengt je naar vijandige gebieden, $N. Bereid je voor.",
  o = "Spreek met Watchmaster Sorigal.",
  c = "Heeft Andromath je gestuurd? Heel goed. Ik heb een belangrijke taak voor je...",
